 function select(id:string,version?:number){if(draftRef.current)setStorageError(storeDraft(draftRef.current));if(id!==activeId)pendingSelection.current={id,version:version??null,frame:0,objectId:'',pose:null};if(id!==activeId||(version??byId.get(id)?.version)!==active?.version||frame!==0)setSample(null);setActiveId(id);setHistoryVersion(version??null);setFrame(0);setDraftPose(null);}
